    12→
    13→// Increment this each time the protocol upgrades.
    14→const CURRENT_VERSION: u64 = 1;
    15→
    16→/// OTW for package initialization
    17→public struct APP has drop {}
    18→
    19→/// Administrative capability for protocol management
    20→public struct AdminCap has key, store {
    21→    id: UID,
    22→}
    23→
    24→/// Whitelist certain functions in the lending protocol to only certain packages
    25→public struct PackageCallerCap has key, store {
    26→    id: UID,
    27→}
    28→
    29→public struct ReferralKey has copy, drop, store {}
    30→public struct PackageWhitestKey has copy, drop, store {}
    31→
    32→/// Main protocol application state
    33→public struct ProtocolApp has key, store {
    34→    id: UID,
    35→    version: u64,
    36→    markets: Table<TypeName, ID>,
    37→
    38→    // dynamic fields:
    39→    // - referral (Referral)
    40→    // - package_whitelist (VecSet<ID>)
    41→}
    42→
    43→/// Initialize the protocol
    44→fun init(otw: APP, ctx: &mut TxContext) {
    45→    package::claim_and_keep(otw, ctx);
    46→
    47→    let (admin_cap, app) = create(ctx);
    48→
    49→    transfer::transfer(admin_cap, ctx.sender());
    50→    transfer::public_share_object(app);
    51→}
    52→
    53→fun create(ctx: &mut TxContext): (AdminCap, ProtocolApp) {
    54→    // Create and transfer admin capability to deployer
    55→    let admin_cap = AdminCap { id: object::new(ctx) };
    56→
    57→    // Create and share protocol application object
    58→    let mut app = ProtocolApp {
    59→        id: object::new(ctx),
    60→        version: CURRENT_VERSION,
    61→        markets: table::new(ctx),
    62→    };
    63→
    64→    dynamic_field::add(&mut app.id, ReferralKey {}, referral::default(ctx));
    65→    dynamic_field::add(&mut app.id, PackageWhitestKey {}, vec_map::empty<ID, u32>());
    66→
    67→    (admin_cap, app)
    68→}
    69→
    70→// ==================== Public Getter Functions ====================
    71→public fun permissions(self: &ProtocolApp, cap: &PackageCallerCap): u32 {
    72→    let whitelist = dynamic_field::borrow<PackageWhitestKey, VecMap<ID, u32>>(&self.id, PackageWhitestKey {});
    73→
    74→    let id = object::id(cap);
    75→    assert!(whitelist.contains(&id), error::caller_not_whitelisted());
    76→
    77→    *whitelist.get(&id)
    78→}
    79→
    80→public fun current_version(): u64 { CURRENT_VERSION }
    81→
    82→public(package) fun ensure_version_matches(self: &ProtocolApp) {
    83→    assert!(self.version == CURRENT_VERSION, error::version_mismatch());
    84→}
